from bisect import bisect_left

def lisBoundedStep(nums, k):
    vals = sorted(set(nums))
    m = len(vals)
    tree = [0] * (2 * m)
    best = 0
    for x in nums:
        lo = bisect_left(vals, x - k) + m
        hi = bisect_left(vals, x) + m
        res = 0
        while lo < hi:
            if lo & 1:
                if tree[lo] > res:
                    res = tree[lo]
                lo += 1
            if hi & 1:
                hi -= 1
                if tree[hi] > res:
                    res = tree[hi]
            lo >>= 1
            hi >>= 1
        cur = res + 1
        p = bisect_left(vals, x) + m
        if cur > tree[p]:
            tree[p] = cur
            p >>= 1
            while p >= 1:
                v = max(tree[2 * p], tree[2 * p + 1])
                if tree[p] == v:
                    break
                tree[p] = v
                p >>= 1
        if cur > best:
            best = cur
    return best
